selector_to_html = {"a[href=\"#benchmark\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Benchmark \u62a5\u544a<a class=\"headerlink\" href=\"#benchmark\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#coverage\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Coverage \u62a5\u544a<a class=\"headerlink\" href=\"#coverage\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6b65\u9aa4 1\uff1a\u6ce8\u518c\u4ed3\u5e93<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#github-workflow-runner\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6b65\u9aa4 3\uff1a\u914d\u7f6e GitHub Workflow Runner<a class=\"headerlink\" href=\"#github-workflow-runner\" title=\"Link to this heading\">#</a></h2><p>\u4fee\u6539 GitHub Action workflow \u4e2d <code class=\"docutils literal notranslate\"><span class=\"pre\">runs-on</span></code> \u6807\u7b7e\u914d\u7f6e\uff0c<code class=\"docutils literal notranslate\"><span class=\"pre\">runs-on</span></code> \u4e2d\u7684\u6807\u7b7e\u4e3a\u6b65\u9aa4 2 \u521b\u5efa\u7684 Runner Scale Sets \u7684 name\u3002</p>", "a[href=\"#runner-scale-sets\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6b65\u9aa4 2\uff1a\u521b\u5efa Runner Scale Sets<a class=\"headerlink\" href=\"#runner-scale-sets\" title=\"Link to this heading\">#</a></h2><p>\u5b8c\u6210\u540e\u53ef\u5728 GitHub \u7684 Action Runner \u5904\u770b\u5230\u521b\u5efa\u597d\u7684 runner set\u3002</p>", "a[href=\"../glossary/index.html#term-DooD\"]": "<dt id=\"term-DooD\">DooD</dt><dd><p>Docker-outside-of-Docker\uff0c\u4f7f\u7528\u5bbf\u4e3b\u673a Docker daemon \u7684\u5bb9\u5668\u5316\u65b9\u6848\uff0c\u6027\u80fd\u9ad8\u4f46\u98ce\u9669\u9ad8\uff0c\u4ec5\u5bf9\u7279\u6743\u7528\u6237\u5f00\u653e\u3002</p></dd>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u767b\u5f55\u5e73\u53f0<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u9996\u6b21\u4f7f\u7528 FlagCICD \u5e73\u53f0\u9700\u8981\u5148\u767b\u5f55\u3002</p>", "a[href=\"../glossary/index.html#term-DinD\"]": "<dt id=\"term-DinD\">DinD</dt><dd><p>Docker-in-Docker\uff0c\u5728 Docker \u5bb9\u5668\u5185\u8fd0\u884c Docker \u7684\u6280\u672f\u65b9\u6848\uff0c\u9694\u79bb\u6027\u597d\u4f46 docker run \u4e0d\u53ef\u8bbf\u95ee\u52a0\u901f\u5361\u8d44\u6e90\u3002</p></dd>", "a[href=\"#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e0b\u4e00\u6b65<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6b65\u9aa4 4\uff1a\u4e0a\u4f20\u6d4b\u8bd5\u62a5\u544a<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><h3>Coverage \u62a5\u544a<a class=\"headerlink\" href=\"#coverage\" title=\"Link to this heading\">#</a></h3>", "a[href=\"../glossary/index.html#term-Runner\"]": "<dt id=\"term-Runner\">Runner</dt><dd><p>\u6267\u884c CI/CD \u5de5\u4f5c\u6d41\u7684\u4ee3\u7406\u7a0b\u5e8f\u3002</p></dd>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u524d\u7f6e\u4f9d\u8d56<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>\u5e73\u53f0\u901a\u8fc7 Action Runner Controller \u52a8\u6001\u62c9\u8d77 GitHub Action Runner\uff0c\u7528\u6237\u53ef\u5728\u62c9\u8d77\u7684 runner \u4e2d\u4f7f\u7528 docker image \u62c9\u8d77\u73af\u5883\uff0c\u4e0d\u652f\u6301\u76f4\u63a5\u5728\u88f8\u673a\u4e0a\u8fd0\u884c\u6d4b\u8bd5\uff0c\u56e0\u6b64\u9700\u7528\u6237\u81ea\u5907\u53ef docker pull \u7684\u955c\u50cf\u3002</p>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5feb\u901f\u5165\u95e8<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u672c\u6307\u5357\u5e2e\u52a9\u60a8\u5feb\u901f\u5f00\u59cb\u4f7f\u7528 FlagCICD \u5e73\u53f0\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
